def pbr(m):
 assert m and m.use_nodes;p=m.node_tree.nodes.get('Principled BSDF');assert p is not None
 assert not any(n.type.startswith('TEX_') for n in m.node_tree.nodes),'No texture nodes'
 assert not any(socket.is_linked for socket in p.inputs),'No linked PBR input'
 values=[]
 for name in ['Base Color','Metallic','Roughness','Alpha','IOR','Specular IOR Level','Transmission Weight','Coat Weight','Coat Roughness','Sheen Weight','Emission Color','Emission Strength']:
  value=p.inputs[name].default_value;values.append((name,tuple(round(float(x),6) for x in value) if hasattr(value,'__len__') else round(float(value),6)))
 values.append(('double_sided',not m.use_backface_culling));return tuple(values)
def matrix64(m):return tuple(tuple(float(m[i][j]) for j in range(4)) for i in range(4))
def mm64(a,b):return tuple(tuple(sum(a[i][k]*b[k][j] for k in range(4)) for j in range(4)) for i in range(4))
def point64(m,p):return tuple(sum(m[i][j]*float(p[j]) for j in range(3))+m[i][3] for i in range(3))
def rigid64(position,degrees):
 a=math.radians(degrees);c=math.cos(a);s=math.sin(a);x,y,z=map(float,position)
 return ((c,-s,0.,x),(s,c,0.,y),(0.,0.,1.,z),(0.,0.,0.,1.))
def inverse_rigid64(m):
 r=tuple(tuple(m[j][i] for j in range(3)) for i in range(3))
 return tuple(tuple(r[i][j] for j in range(3))+(-sum(r[i][j]*m[j][3] for j in range(3)),) for i in range(3))+((0.,0.,0.,1.),)
def rows(objects,transform=None):
 out=[];cache={}
 def world64(o):
  if o not in cache:
   local=matrix64(o.matrix_basis)
   cache[o]=mm64(mm64(world64(o.parent),matrix64(o.matrix_parent_inverse)),local) if o.parent is not None else local
  return cache[o]
 for o in objects:
  o.data.calc_loop_triangles();world=world64(o);v=[point64(world,p.co) for p in o.data.vertices]
  if transform is not None:v=[point64(transform,p) for p in v]
  for t in o.data.loop_triangles:out.append((tuple(v[i] for i in t.vertices),pbr(o.data.materials[t.material_index])))
 return out
def centroid64(p):return Vector(tuple(sum(q[k] for q in p)/3 for k in range(3)))
def match(actual,expected,label):
 assert len(actual)==len(expected),(label,'triangle count',len(actual),len(expected));kd=KDTree(len(expected))
 for i,(p,m) in enumerate(expected):kd.insert(centroid64(p),i)
 kd.balance();used=set();maximum=0.
 for p,m in actual:
  candidates=[]
  for c,i,d in kd.find_range(centroid64(p),TOL*4):
   if i in used or expected[i][1]!=m:continue
   q=expected[i][0];err=min(max(abs(float(p[(j+s)%3][k]-q[j][k])) for j in range(3) for k in range(3)) for s in range(3))
   if err<=TOL:candidates.append((err,i))
  assert candidates,(label,'oriented triangle/full PBR mismatch',list(p[0]),m)
  err,i=min(candidates);used.add(i);maximum=max(maximum,err)
 assert len(used)==len(expected)
 return {'label':label,'triangles_matched_once':len(actual),'max_coordinate_error_m':maximum,'tolerance_m':TOL,'full_solid_pbr_match':True,'reverse_winding_allowed':False}
def digest(rr):
 r=sorted((min(tuple(tuple(round(float(c),6) for c in xyz[(i+j)%3]) for i in range(3)) for j in range(3)),mat) for xyz,mat in rr)
 return hashlib.sha256(json.dumps(r,separators=(',',':')).encode()).hexdigest()
